  function push(chunk) {
    if (ended) throw new Error('push() called after end()');
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
    const records = [];
    let i = 0;
    if (!started && chunk.length > 0) {
      started = true;
      if (chunk.charCodeAt(0) === 0xfeff) i = 1;
    }
    for (; i < chunk.length; i++) {
      const ch = chunk[i];
      const wasCR = prevCR;
      prevCR = ch === '\r';
      if (ch === '\r' || (ch === '\n' && !wasCR)) line++;

      if (state === QUOTED) {
        if (ch === '"') state = QUOTE;
        else field += ch;
        continue;
      }
      if (state === QUOTE) {
        if (ch === '"') {
          field += '"';
          state = QUOTED;
          continue;
        }
        if (ch !== delimiter && ch !== '\r' && ch !== '\n') {
          throw new SyntaxError(`Unexpected character after closing quote at line ${line}`);
        }
      }
      if (ch === delimiter) {
        row.push(field);
        field = '';
        rowStarted = true;
        state = FIELD_START;
      } else if (ch === '\r' || ch === '\n') {
        // LF of a CRLF whose CR already ended the record.
        if (ch === '\n' && wasCR && !rowStarted && state === FIELD_START) continue;
        row.push(field);
        records.push(row);
        row = [];
        field = '';
        rowStarted = false;
        state = FIELD_START;
      } else if (state === FIELD_START && ch === '"') {
        rowStarted = true;
        state = QUOTED;
      } else {
        field += ch;
        rowStarted = true;
        state = UNQUOTED;
      }
    }
    return records;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === QUOTED) throw new SyntaxError(`Unterminated quoted field at line ${line}`);
    if (!rowStarted) return [];
    row.push(field);
    const last = row;
    row = [];
    field = '';
    rowStarted = false;
    return [last];
  }

  return { push, end };
}

/**
 * Parse all text using the same grammar and validation as createParser.
 * With options.header === true, convert records with the existing
 * toObjects(records, { header: true }) helper; otherwise return string[][].
 * Empty input yields [] in either mode. Do not change the helper's contract.
 */
function parse(text, options = {}) {
  const parser = createParser(options);
  const records = parser.push(text).concat(parser.end());
  return options.header === true ? toObjects(records, { header: true }) : records;
}

module.exports = { createParser, parse };
